create table if not exists projects(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id) on delete cascade,channel_id uuid not null references channels(id) on delete cascade,name text not null,mode text not null default 'manual',status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists project_versions(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,version int not null,data jsonb not null,created_at timestamptz not null default now(),unique(project_id,version));
